edits.before:
exitEditMode(options = undefined) {
  if (this.inline || !this.picker.active || this.editMode) {
    return;
  }
  const opts = Object.assign({update: false}, options);
  delete this.editMode;
  this.inputField.classList.remove('in-edit');
  if (opts.update) {
    this.update(opts);
  }
}

